composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      DB_HOST: "{{serviceName}}-mysql"
      DB_DATABASE: linkace
      DB_USERNAME: linkace
      DB_PASSWORD: {{env.DB_PASSWORD}}
      APP_KEY: {{env.APP_KEY}}
      APP_URL: {{env.APP_URL}}
    volumes:
      - {{appDataPath}}/data:/var/www/html/storage
    depends_on:
      - {{serviceName}}-mysql
  {{serviceName}}-mysql:
    image: mysql:8
    container_name: {{serviceName}}-mysql
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: linkace
      MYSQL_USER: linkace
      MYSQL_PASSWORD: {{env.DB_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.DB_PASSWORD}}
    volumes:
      - {{appDataPath}}/mysql:/var/lib/mysql
